std::vector<PolygonWithHoles2d> result;
if (P1.empty() || P2.empty()) return result;

using K = CGAL::Exact_predicates_exact_constructions_kernel;
using PointCgal = K::Point_2;
using PolygonCgal = CGAL::Polygon_2<K>;
using PolygonWithHolesCgal = CGAL::Polygon_with_holes_2<K>;

auto to_cgal = [](const Polygon2d& poly) -> PolygonCgal {
    PolygonCgal p;
    for (const auto& pt : poly) {
        p.push_back(PointCgal(pt.x(), pt.y()));
    }
    return p;
};

auto to_poly2d = [](const PolygonCgal& poly) -> Polygon2d {
    Polygon2d p;
    for (auto it = poly.vertices_begin(); it != poly.vertices_end(); ++it) {
        p.emplace_back(it->x().exact().to_double(), it->y().exact().to_double());
    }
    return p;
};

PolygonCgal cgal_p1 = to_cgal(P1);
PolygonCgal cgal_p2 = to_cgal(P2);

if (!cgal_p1.is_simple() || !cgal_p2.is_simple()) return result;

std::list<PolygonWithHolesCgal> intersections;
CGAL::intersection(cgal_p1, cgal_p2, std::back_inserter(intersections));

for (const auto& poly_with_holes : intersections) {
    PolygonWithHoles2d pwh;
    pwh.outer = to_poly2d(poly_with_holes.outer_boundary());

    for (auto hit = poly_with_holes.holes_begin(); hit != poly_with_holes.holes_end(); ++hit) {
        pwh.holes.emplace_back(to_poly2d(*hit));
    }

    result.emplace_back(std::move(pwh));
}

return result;
// END_CODE

